CREATE TABLE "new__store_order" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "currency" varchar(3) NOT NULL, "status" varchar(16) NOT NULL, "total_cents" integer unsigned NOT NULL CHECK ("total_cents" >= 0), "stripe_checkout_session_id" varchar(255) NULL UNIQUE, "stripe_payment_intent_id" varchar(255) NOT NULL, "customer_email" varchar(254) NOT NULL, "shipping_name" varchar(120) NOT NULL, "shipping_line1" varchar(200) NOT NULL, "shipping_line2" varchar(200) NOT NULL, "shipping_city" varchar(120) NOT NULL, "shipping_state" varchar(120) NOT NULL, "shipping_postal_code" varchar(20) NOT NULL, "shipping_country" varchar(2) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "paid_at" datetime NULL, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "shipping_status" varchar(24) NOT NULL, "stripe_customer_id" varchar(255) NOT NULL);
INSERT INTO "new__store_order" ("id", "status", "total_cents", "stripe_checkout_session_id", "stripe_payment_intent_id", "customer_email", "shipping_name", "shipping_line1", "shipping_line2", "shipping_city", "shipping_state", "shipping_postal_code", "shipping_country", "created_at", "updated_at", "paid_at", "user_id", "shipping_status", "stripe_customer_id", "currency") SELECT "id", "status", "total_cents", "stripe_checkout_session_id", "stripe_payment_intent_id", "customer_email", "shipping_name", "shipping_line1", "shipping_line2", "shipping_city", "shipping_state", "shipping_postal_code", "shipping_country", "created_at", "updated_at", "paid_at", "user_id", "shipping_status", "stripe_customer_id", "currency" FROM "store_order";
DROP TABLE "store_order";
ALTER TABLE "new__store_order" RENAME TO "store_order";
CREATE INDEX "store_order_status_69bd39aa" ON "store_order" ("status");
