CREATE INDEX "store_order_shipping_status_d4e398e0" ON "store_order" ("shipping_status");
CREATE TABLE "new__store_product" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(120) NOT NULL, "slug" varchar(140) NOT NULL UNIQUE, "sku" varchar(40) NOT NULL, "price_cents" integer unsigned NOT NULL CHECK ("price_cents" >= 0), "stock" integer unsigned NOT NULL CHECK ("stock" >= 0), "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "stripe_product_id" varchar(255) NOT NULL, "stripe_price_id" varchar(255) NOT NULL, "short_description" varchar(280) NOT NULL, "long_description" text NOT NULL, "currency" varchar(3) NOT NULL);
INSERT INTO "new__store_product" ("id", "name", "slug", "sku", "price_cents", "stock", "is_active", "created_at", "updated_at", "stripe_product_id", "stripe_price_id", "short_description", "long_description", "currency") SELECT "id", "name", "slug", "sku", "price_cents", "stock", "is_active", "created_at", "updated_at", "stripe_product_id", "stripe_price_id", "short_description", "long_description", "currency" FROM "store_product";
